function h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
/** Resolve local CMS image paths safely; if an uploaded image is missing, use a bundled ASPI image. */
function public_image(string $value,string $fallback='assets/campus-1.webp'): string {
 $value=trim($value); if($value==='') $value=$fallback;
 if(preg_match('~^(https?:)?//~i',$value)) return $value;
 $clean=str_replace('\\','/',$value); $clean=preg_replace('~[?#].*$~','',$clean); $clean=ltrim($clean,'/');
 if($clean!=='' && !str_contains($clean,'..')) {
  foreach([__DIR__.'/'.$clean,__DIR__.'/live/'.$clean] as $candidate) { if(is_file($candidate) && is_readable($candidate)) return '/'.ltrim(str_replace(__DIR__,'',$candidate),'/'); }
 }
 return '/'.ltrim($fallback,'/');
}
