.diploma-program-card:hover .diploma-program-photo img{transform:scale(1.04)}
.diploma-program-photo:after{content:"";position:absolute;inset:40% 0 0;background:linear-gradient(transparent,#0b1b3b9c)}
.diploma-code-badge{position:absolute;z-index:1;top:15px;left:15px;background:#fff;color:var(--navy);border:1px solid #ffffffa8;border-radius:999px;padding:6px 13px;font-size:12px;font-weight:900;box-shadow:0 6px 20px #081a3220}
.diploma-program-content{padding:23px 25px 25px;display:flex;flex-direction:column;flex:1}
