.diploma-facts{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:auto}
.diploma-fact{padding:12px 13px;background:#f3f7fb;border:1px solid #e0e9f2;border-radius:12px;min-width:0}
.diploma-fact small{display:block;color:var(--muted);font-size:11px;font-weight:700}
.diploma-fact b{display:block;color:var(--navy);font-size:14px;overflow-wrap:anywhere}
.diploma-status{display:inline-flex;align-items:center;gap:7px;color:#087b61;background:#e8f8f1;border:1px solid #c6efdd;border-radius:999px;padding:5px 10px;font-size:11px;font-weight:900;align-self:flex-start;margin-top:14px}
.diploma-status:before{content:"";width:7px;height:7px;background:#10a779;border-radius:50%}
.gallery-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:15px}
.gallery-item{position:relative;display:block;overflow:hidden;border-radius:17px;aspect-ratio:4/3;background:#e9eff6;border:1px solid var(--line);box-shadow:0 12px 28px #10224b0b}
.gallery-item img{width:100%;height:100%;object-fit:cover;display:block;transition:transform .45s}
.gallery-item:hover img{transform:scale(1.07)}
.gallery-item span{position:absolute;left:0;right:0;bottom:0;padding:28px 13px 12px;color:#fff;font-weight:700;font-size:13px;background:linear-gradient(transparent,#07152dd9)}
