/* ASPI responsive design refinement */
a,a:hover,a:focus,a:visited{text-decoration:none!important;border-bottom:0!important}
button,input,select,textarea{max-width:100%}
img{height:auto}
.hero-grid,.container,.section-grid,.trustgrid{min-width:0}
.hero-card{border-radius:26px;overflow:hidden;box-shadow:0 24px 65px #02081755;border:1px solid #ffffff55;transform:translateY(0);animation:aspiHeroCard .8s ease-out both}
.hero-card>img{display:block;width:100%;height:clamp(260px,34vw,430px);object-fit:cover}
.hero-chip{backdrop-filter:blur(14px)}
@keyframes aspiHeroCard{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:translateY(0)}}
section[id],main section{scroll-margin-top:100px}
