/* Premium ASPI v2 navigation and hero */
a,a:hover,a:focus,a:visited{text-decoration:none!important;border-bottom:0!important}
.hero{min-height:clamp(500px,58vw,650px);display:flex;align-items:center;padding:clamp(64px,9vw,110px) 0 clamp(100px,12vw,140px);background-image:linear-gradient(100deg,rgba(6,18,43,.94) 0%,rgba(10,33,70,.78) 56%,rgba(5,100,112,.58) 100%),url('<?=h($heroImage)?>');background-position:center;background-size:cover;background-repeat:no-repeat;border-radius:0 0 9% 9% / 0 0 7% 7%}
.hero-grid{display:block;max-width:var(--max)}
.hero-copy{max-width:800px;padding:clamp(0px,2vw,20px) 0;position:relative;z-index:2}
.hero h1{max-width:820px;font-size:clamp(38px,5.2vw,68px);line-height:1.22;text-wrap:balance;text-shadow:0 4px 22px #06132b30}
.hero p{max-width:680px;font-size:clamp(16px,1.6vw,19px);line-height:1.9}
.hero:before{content:"";position:absolute;width:min(50vw,620px);height:min(50vw,620px);border:1px solid #ffffff24;border-radius:46% 54% 63% 37% / 41% 43% 57% 59%;right:-9%;top:-22%;z-index:0;transform:rotate(-18deg);pointer-events:none}
.hero:after{content:"";position:absolute;z-index:0;inset:auto -3% -75px;height:145px;background:#fff;border-radius:50% 50% 0 0 / 65% 65% 0 0;pointer-events:none}
.hero-card{display:none!important}
.navlinks{gap:clamp(8px,1.3vw,18px);font-size:14px}
.nav-dropdown{position:relative}
.nav-dropbtn{display:inline-flex;align-items:center;gap:7px;border:0;background:transparent;padding:12px 0;color:inherit;font-weight:700;cursor:pointer;white-space:nowrap}
.nav-dropbtn i{font-size:10px;transition:transform .2s}
.nav-dropdown.is-open .nav-dropbtn i{transform:rotate(180deg)}
.nav-dropmenu{position:absolute;left:0;top:calc(100% + 9px);min-width:230px;padding:8px;background:#fff;border:1px solid #e4e9f2;border-radius:15px;box-shadow:0 20px 55px #10224b20;display:none;z-index:80}
.nav-dropdown.is-open .nav-dropmenu{display:grid;animation:dropIn .18s ease-out}
.nav-dropmenu a{padding:11px 13px;border-radius:9px;color:#35425b;white-space:normal}
.nav-dropmenu a:hover{background:#eef8f8;color:var(--teal)}
@keyframes dropIn{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:translateY(0)}}
.message-card{border-radius:22px;padding:25px;display:flex;flex-direction:column;min-width:0;min-height:100%;background:linear-gradient(150deg,#fff,#f6fbff);box-shadow:0 18px 42px #10224b0b;transition:transform .22s,box-shadow .22s}
.message-card:hover{transform:translateY(-4px);box-shadow:0 24px 55px #10224b15}
.message-preview{display:-webkit-box!important;-webkit-line-clamp:4!important;-webkit-box-orient:vertical!important;overflow:hidden!important;line-height:1.8;min-height:calc(1.8em * 4);overflow-wrap:anywhere;word-break:normal}
.message-actions{margin-top:auto!important;padding-top:16px}
.message-read{min-height:40px;white-space:nowrap}
.message-modal{z-index:9999;backdrop-filter:blur(8px)}
.message-modal.open{display:flex!important;visibility:visible!important;opacity:1}
