$gi['alt_text']?:$gi['title'])?>" loading="lazy"><span><?=h($gi['title']?:'ASPI ক্যাম্পাস ও কার্যক্রম')?></span></a><?php endforeach;?><?php if(!$galleryImages):?><a class="gallery-item reveal" href="assets/campus-1.webp" target="_blank" rel="noopener"><img src="assets/campus-1.webp" alt="ASPI ক্যাম্পাস" loading="lazy"><span>আমাদের ক্যাম্পাস</span></a><a class="gallery-item reveal" href="assets/campus-2.webp" target="_blank" rel="noopener"><img src="assets/campus-2.webp" alt="ASPI প্রশিক্ষণ" loading="lazy"><span>প্রশিক্ষণ কার্যক্রম</span></a><a class="gallery-item reveal" href="assets/campus-3.webp" target="_blank" rel="noopener"><img src="assets/campus-3.webp" alt="ASPI ল্যাব" loading="lazy"><span>ল্যাব ও ব্যবহারিক শিক্ষা</span></a><a class="gallery-item reveal" href="assets/campus-5.jpg" target="_blank" rel="noopener"><img src="assets/campus-5.jpg" alt="ASPI প্রতিষ্ঠান" loading="lazy"><span>প্রতিষ্ঠানের পরিবেশ</span></a><?php endif;?></div></div></section><section class="section soft" id="news"><div class="container"><div class="section-head"><div class="kicker">News · Events · Workshops</div><h2>সাম্প্রতিক খবর, অনুষ্ঠান ও কর্মশালা</h2><p>প্রতিষ্ঠানের অনুষ্ঠান, প্রশিক্ষণ, কর্মশালা, অর্জন ও সংবাদচিত্রের বিস্তারিত আপডেট।</p></div><div class="post-grid"><?php foreach($latestPosts as $post):?><article class="post-card reveal"><a class="post-cover" href="live/post.php?id=<?=(int)$post['id']?>"><img src="<?=h(public_image((string)($post['cover_image']??''),'assets/campus-1.webp'))?>" alt="<?=h($post['title'])?>" loading="lazy"></a><div class="post-copy"><span class="post-tag"><?=h(['news'=>'খবর','event'=>'অনুষ্ঠান','workshop'=>'কর্মশালা','notice'=>'আপডেট'][$post['category']]??'আপডেট')?></span><h3><a href="live/post.php?id=<?=(int)$post['id']?>"><?=h($post['title'])?></a></h3><p><?=h($post['excerpt'])?></p><a class="post-more" href="live/post.php?id=<?=(int)$post['id']?>">বিস্তারিত পড়ুন <i class="fa-solid fa-arrow-right"></i></a></div></article><?php endforeach;?><?php if(!$latestPosts):?><div class="post-empty">অনুষ্ঠান, কর্মশালা ও খবরের আপডেট শিগগিরই প্রকাশ করা হবে।</div><?php endif;?></div><div style="text-align:center;margin-top:25px"><a class="btn btn-outline-primary" href="live/posts.php">সকল খবর ও ইভেন্ট দেখুন <i class="fa-solid fa-arrow-right"></i></a></div></div></section><section class="section application" id="apply"><div class="container apply-grid"><div class="apply-copy"><div class="kicker">Course Enquiry</div><h2>আপনার দক্ষতা উন্নয়নের যাত্রা শুরু করুন</h2><p>আপনার পছন্দের NSDA কোর্স নির্বাচন করে যোগাযোগের তথ্য দিন। ভর্তি সংক্রান্ত বিস্তারিত জানাতে আমাদের টিম আপনার সঙ্গে যোগাযোগ করবে।</p><div class="apply-points"><div><i class="fa-solid fa-circle-check"></i><span>চলমান কোর্স ও ব্যাচ সম্পর্কে তথ্য</span></div><div><i class="fa-solid fa-circle-check"></i><span>প্রশিক্ষণের সময়সূচি ও প্রয়োজনীয় যোগ্যতা</span></div><div><i class="fa-solid fa-circle-check"></i><span>আবেদন জমার পর প্রতিষ্ঠানের পক্ষ থেকে যোগাযোগ</span></div></div></div><div class="apply-form"><h3>কোর্সে আগ্রহ প্রকাশ করুন</h3><p>নিচের ফরম পূরণ করুন। আপনার তথ্য অ্যাডমিন ড্যাশবোর্ডে সংরক্ষিত হবে।</p><?php if($flash):?><div class="alert success" role="status"><i class="fa-solid fa-circle-check"></i> <?=h($flash)?></div><?php endif;?><?php if($error):?><div class="alert error" role="alert"><?=h($error)?></div><?php endif;?><form method="post" action="#apply"><input type="hidden" name="form_action" value="apply"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><div class="form-grid"><div class="field"><label for="applicant_name">আপনার নাম *</label><input id="applicant_name" name="applicant_name" required minlength="2" maxlength="180" autocomplete="name" value="<?=h($_POST['applicant_name']??'')?>"></div><div class="field"><label for="phone">মোবাইল নম্বর *</label><input id="phone" name="phone" required minlength="8" maxlength="25" inputmode="tel" autocomplete="tel" value="<?=h($_POST['phone']??'')?>"></div><div class="field full"><label for="course_id">পছন্দের NSDA কোর্স *</label><select id="course_id" name="course_id" required><option value="">কোর্স নির্বাচন করুন</option><?php foreach($courses as $c):?><option value="<?=(int)$c['id']?>" <?=((int)($_POST['course_id']??0)===(int)$c['id'])?'selected':''?>><?=h($c['title'].' — '.$c['level_label'])?></option><?php endforeach;?></select></div><div class="field full"><label for="education">সর্বশেষ শিক্ষাগত যোগ্যতা</label><input id="education" name="education" maxlength="180" placeholder="যেমন: SSC / HSC / অন্যান্য" value="<?=h($_POST['education']??'')?>"></div><div class="field full"><label for="message">আপনার প্রশ্ন (ঐচ্ছিক)</label><textarea id="message" name="message" maxlength="2000" placeholder="কোর্স বা ব্যাচ সম্পর্কে জানতে চাইলে লিখুন"><?=h($_POST['message']??'')?></textarea></div></div><button class="btn submit" type="submit">আবেদন জমা দিন <i class="fa-solid fa-paper-plane"></i></button></form></div></div></section></main><?php require __DIR__.'/live/app/public-footer.php'; ?>
<div class="message-modal" id="messageModal" role="dialog" aria-modal="true" aria-hidden="true" aria-labelledby="messageModalName"><div class="message-modal-card"><button class="message-modal-close" type="button" id="messageModalClose" aria-label="বন্ধ করুন"><i class="fa-solid fa-xmark"></i></button><div class="message-modal-head"><img id="messageModalPhoto" src="" alt="" hidden><div id="messageModalPlaceholder" class="message-profile message-profile-placeholder"><i class="fa-solid fa-user-tie"></i></div><div><div class="message-role" id="messageModalRole"></div><h3 id="messageModalName"></h3></div></div><div class="message-modal-text" id="messageModalText"></div></div></div>
<script>
(()=>{const toggle=document.getElementById('navToggle'),nav=document.getElementById('navLinks');document.querySelectorAll('img').forEach(img=>img.addEventListener('error',()=>{if(img.dataset.aspiFallbackDone)return;img.dataset.aspiFallbackDone='1';const alt=(img.alt||'').toLowerCase();img.src=alt.includes('ল্যাব')||alt.includes('প্রশিক্ষণ')?'/assets/campus-3.webp':'/assets/campus-1.webp';}));document.querySelectorAll('.nav-dropbtn').forEach(b=>b.addEventListener('click',()=>{const box=b.closest('.nav-dropdown'),open=box.classList.toggle('is-open');b.setAttribute('aria-expanded',open?'true':'false');document.querySelectorAll('.nav-dropdown').forEach(other=>{if(other!==box){other.classList.remove('is-open');other.querySelector('.nav-dropbtn')?.setAttribute('aria-expanded','false');}});}));toggle?.addEventListener('click',()=>{const open=nav.classList.toggle('open');toggle.setAttribute('aria-expanded',open?'true':'false');toggle.innerHTML=open?'<i class="fa-solid fa-xmark"></i>':'<i class="fa-solid fa-bars"></i>';});nav?.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');toggle?.setAttribute('aria-expanded','false');}));document.querySelectorAll('[data-course]').forEach(a=>a.addEventListener('click',()=>{const select=document.getElementById('course_id');if(select)select.value=a.dataset.course;}));const modal=document.getElementById('messageModal'),closeModal=()=>{if(!modal)return;modal.classList.remove('open');modal.setAttribute('aria-hidden','true');document.body.style.overflow='';};document.querySelectorAll('[data-message-open]').forEach(btn=>btn.addEventListener('click',()=>{document.getElementById('messageModalName').textContent=btn.dataset.name||'';document.getElementById('messageModalRole').textContent=btn.dataset.role||'';document.getElementById('messageModalText').textContent=btn.dataset.message||'';const photo=document.getElementById('messageModalPhoto'),placeholder=document.getElementById('messageModalPlaceholder');if(btn.dataset.photo){photo.src=btn.dataset.photo;photo.alt=btn.dataset.name||'';photo.hidden=false;placeholder.hidden=true;}else{photo.hidden=true;photo.removeAttribute('src');placeholder.hidden=false;}modal.classList.add('open');modal.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';document.getElementById('messageModalClose').focus();}));document.getElementById('messageModalClose')?.addEventListener('click',closeModal);modal?.addEventListener('click',e=>{if(e.target===modal)closeModal();});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});const els=document.querySelectorAll('.reveal');if('IntersectionObserver'in window){const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');io.unobserve(e.target)}}),{threshold:.12});els.forEach(el=>io.observe(el));}else els.forEach(el=>el.classList.add('visible'));})();
</script>
</body></html>
